        cwd=ROOT, check=True,
    )
    out_dir = os.path.join(SC, "summaries", "pdf")
    os.makedirs(out_dir, exist_ok=True)
    out = os.path.join(out_dir, f"{cid}_{slug}.pdf")
    ud = tempfile.mkdtemp(prefix="scj_chrome_")
    subprocess.run(
250→        [chrome, "--headless=new", "--disable-gpu", "--no-sandbox",
