         f"--print-to-pdf={out}", file_uri(html)],
        check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
    )
    if not os.path.exists(out) or os.path.getsize(out) < 1000:
        die(f"digest PDF missing or too small: {out}")
    return out


